  "Make a game loop ↗": { es: "Crear un bucle para el juego ↗", ar: "اصنع حلقة موسيقية للعبة ↗", zh: "制作游戏循环音乐 ↗", sw: "Tengeneza muziki wa mzunguko ↗", sv: "Gör en spelslinga ↗", de: "Eine Spielschleife machen ↗", pt: "Fazer um loop de jogo ↗", fr: "Créer une boucle de jeu ↗" },
